<?php
namespace Tests\Feature; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Hash; use Tests\TestCase;
class AuthenticationTest extends TestCase { use RefreshDatabase; public function test_user_can_register():void{$r=$this->post('/register',['name'=>'Ahmed Ali','email'=>'ahmed@example.com','password'=>'password123','password_confirmation'=>'password123']);$r->assertRedirect('/');$this->assertAuthenticated();$this->assertTrue(Hash::check('password123',User::first()->password));} public function test_user_can_login_and_logout():void{$u=User::factory()->create(['password'=>Hash::make('password123')]);$this->post('/login',['email'=>$u->email,'password'=>'password123'])->assertRedirect('/');$this->assertAuthenticatedAs($u);$this->post('/logout')->assertRedirect('/');$this->assertGuest();} public function test_registration_validation():void{$this->post('/register',['name'=>'1','email'=>'bad','password'=>'short','password_confirmation'=>'short'])->assertSessionHasErrors(['name','email','password']);} }
